-- =============================================================================
-- seed-real-data.sql  (auto-generated by scripts/generate-real-seed-sql.py)
--
-- Standalone seed for the production Windows 10 POS — run AFTER backend's
-- first start (which created the schema and core data via SeedCoreData).
--
-- How to run (on Windows, after start-pos.bat has run at least once):
--     psql -h 127.0.0.1 -U posuser -d poslabs -f seed-real-data.sql
--   …or just double-click load-real-data.bat in the same folder.
--
-- This script adds:
--   0. UTF-8 client_encoding + UPDATE-NULL repair for any pre-existing data
--   1. role.cashier + pos1 user + user_branch link + addresses:read perm
--   2. 15 Thai categories (CAT001-CAT015)
--   3. 21 Thai units (id = Thai name, e.g. 'แผ่น') — atop the 7 SeedCoreData units
--   4. Fixed pos_secret for POS001 (must match Flutter --dart-define=POS_SECRET)
--   5. 1566 part_master rows from xlsx Sheet สินค้า
--   6. 1566 address_master rows (store_id='main', qty=100)
--
-- All inserts use ON CONFLICT DO NOTHING so this script is safe to re-run.
-- =============================================================================

SET client_encoding TO 'UTF8';

-- 0) Repair NULL → default for any rows seeded by older scripts
UPDATE "part_master"    SET "bar_code" = '' WHERE "bar_code" IS NULL;
UPDATE "part_master"    SET "details"  = '' WHERE "details"  IS NULL;
UPDATE "part_master"    SET "cost"     = 0  WHERE "cost"     IS NULL;
UPDATE "address_master" SET "shelf"    = '' WHERE "shelf"    IS NULL;
UPDATE "address_master" SET "qty"      = 100 WHERE "qty" IS NULL;
UPDATE "address_master" SET "max"      = 0  WHERE "max"      IS NULL;
UPDATE "address_master" SET "remarks"  = '' WHERE "remarks"  IS NULL;

-- 1) role.cashier + pos1 user
ON CONFLICT ("id") DO NOTHING;

VALUES (
    'pos1-user-fixed-id-00000000000001',
    'pos1',
    'role.cashier',
    'POS Cashier 1',
    '$2b$12$XvFVPxGNgNfUiAWKMISm9upd1dXyKE7FY5CeWhawbWnGVnkCSMFPu',  -- bcrypt('pos123456')
    true,
    false
)
ON CONFLICT ("username") DO NOTHING;

SELECT u."id", '00000'
FROM "user" u
WHERE u."username" = 'pos1'
ON CONFLICT DO NOTHING;

-- Grant addresses:read to cashier (missing in older seed.go)
ON CONFLICT DO NOTHING;

-- 2) Categories (xlsx Sheet ประเภท)
ON CONFLICT ("id") DO NOTHING;

-- 3) Thai units (id = Thai name)
ON CONFLICT ("id") DO NOTHING;

-- 4) Fix pos_secret for POS001 to a known value
--    (must match Flutter --dart-define=POS_SECRET=windows-pos-default-secret)
UPDATE "pos_setting"
   SET "pos_secret" = 'windows-pos-default-secret'
   WHERE "pos_id" = 'POS001';

-- 5) 1566 parts from xlsx Sheet สินค้า
ON CONFLICT ("code") DO NOTHING;

-- Repair older real-data loads where generated addresses were inserted with qty=0.
-- Do not reset addresses that already appear in bill details.
UPDATE "address_master" a
   SET "qty" = 100
 WHERE a."code" ~ '^ADDR[0-9]+$'
   AND a."store_id" = 'main'
   AND COALESCE(a."qty", 0) = 0
   AND NOT EXISTS (
       SELECT 1
         FROM "bill_item_detail" bid
        WHERE bid."address_code" = a."code"
   );

-- 6) 1566 addresses (one per part, store_id='main')
ON CONFLICT ("code") DO NOTHING;

-- Ensure fresh and previously loaded real-data rows have sellable demo stock.
-- Do not reset addresses that already appear in bill details.
UPDATE "address_master" a
   SET "qty" = 100
 WHERE a."code" ~ '^ADDR[0-9]+$'
   AND a."store_id" = 'main'
   AND COALESCE(a."qty", 0) = 0
   AND NOT EXISTS (
       SELECT 1
         FROM "bill_item_detail" bid
        WHERE bid."address_code" = a."code"
   );
